-- Build 425 live operational evidence control plane.
create table if not exists app.master_build425_source_enrollment_evidence(
 enrollment_id uuid primary key,app_id text not null check(app_id in('ai-data-platform','rosevear-ai-hub','rosevear-comms-hub','icamp','yw','devilndove','rosiedazzlers')),source_commit text not null check(source_commit~'^[a-f0-9]{40}$'),endpoint_path text not null check(endpoint_path='/internal/rosevear/sysop/telemetry/v1'),signer_fingerprint text not null check(signer_fingerprint~'^[a-f0-9]{64}$'),signer_enrolled boolean not null,read_token_custody_verified boolean not null,transport_path text not null check(transport_path in('DIRECT_HTTPS','ORIGINAL_HOST_RELAY')),transport_verified boolean not null,owner_reviewed boolean not null,independently_verified boolean not null,evidence_digest text not null check(evidence_digest~'^sha256:[a-f0-9]{64}$'),reviewer_user_hash text not null check(reviewer_user_hash~'^[a-f0-9]{64}$'),observed_at timestamptz not null,expires_at timestamptz not null,recorded_at timestamptz not null default now(),check(expires_at>observed_at));
create table if not exists app.master_build425_telemetry_acceptance_events(
 acceptance_id uuid primary key,receipt_id uuid not null references app.master_build423_sysop_telemetry_receipts(receipt_id),app_id text not null check(app_id in('ai-data-platform','rosevear-ai-hub','rosevear-comms-hub','icamp','yw','devilndove','rosiedazzlers')),source_commit text not null check(source_commit~'^[a-f0-9]{40}$'),state text not null check(state in('PASS','HOLD','FAILED')),transport_verified boolean not null,freshness_verified boolean not null,owner_reviewed boolean not null,independently_verified boolean not null,evidence_digest text not null check(evidence_digest~'^sha256:[a-f0-9]{64}$'),reviewer_user_hash text not null check(reviewer_user_hash~'^[a-f0-9]{64}$'),observed_at timestamptz not null,expires_at timestamptz not null,recorded_at timestamptz not null default now(),check(expires_at>observed_at));
create table if not exists app.master_build425_sysop_procedure_evidence(
 evidence_id uuid primary key,app_id text not null check(app_id in('ai-data-platform','rosevear-ai-hub','rosevear-comms-hub','icamp','yw','devilndove','rosiedazzlers')),procedure_kind text not null check(procedure_kind in('HEARTBEAT','PROCESS_RESTART','HOST_REBOOT','BACKUP_VERIFY','RECOVERY_EXERCISE','MAINTENANCE','INCIDENT_REVIEW')),state text not null check(state in('PASS','HOLD','FAILED')),original_host boolean not null default false,independently_witnessed boolean not null default false,source_owned boolean not null,owner_reviewed boolean not null,independently_verified boolean not null,evidence_digest text not null check(evidence_digest~'^sha256:[a-f0-9]{64}$'),reviewer_user_hash text not null check(reviewer_user_hash~'^[a-f0-9]{64}$'),observed_at timestamptz not null,expires_at timestamptz not null,notes text,recorded_at timestamptz not null default now(),check(expires_at>observed_at),check(procedure_kind<>'HOST_REBOOT' or app_id='rosevear-ai-hub'));
alter table app.master_build425_source_enrollment_evidence enable row level security;alter table app.master_build425_source_enrollment_evidence force row level security;alter table app.master_build425_telemetry_acceptance_events enable row level security;alter table app.master_build425_telemetry_acceptance_events force row level security;alter table app.master_build425_sysop_procedure_evidence enable row level security;alter table app.master_build425_sysop_procedure_evidence force row level security;
create policy b425_enrollment_read on app.master_build425_source_enrollment_evidence for select to ai_data_runtime using(app.current_master_sysop_role() in('owner','operator'));create policy b425_review_read on app.master_build425_telemetry_acceptance_events for select to ai_data_runtime using(app.current_master_sysop_role() in('owner','operator'));create policy b425_sysop_read on app.master_build425_sysop_procedure_evidence for select to ai_data_runtime using(app.current_master_sysop_role() in('owner','operator'));
create policy b425_enrollment_insert on app.master_build425_source_enrollment_evidence for insert to ai_data_runtime with check(app.current_master_sysop_role()='owner' and owner_reviewed);create policy b425_review_insert on app.master_build425_telemetry_acceptance_events for insert to ai_data_runtime with check(app.current_master_sysop_role()='owner' and owner_reviewed);create policy b425_sysop_insert on app.master_build425_sysop_procedure_evidence for insert to ai_data_runtime with check(app.current_master_sysop_role()='owner' and owner_reviewed);
create policy b425_enrollment_protected_read on app.master_build425_source_enrollment_evidence for select to ai_data_protected_runtime using(true);create policy b425_review_protected_read on app.master_build425_telemetry_acceptance_events for select to ai_data_protected_runtime using(true);create policy b425_sysop_protected_read on app.master_build425_sysop_procedure_evidence for select to ai_data_protected_runtime using(true);
grant select,insert on app.master_build425_source_enrollment_evidence,app.master_build425_telemetry_acceptance_events,app.master_build425_sysop_procedure_evidence to ai_data_runtime;grant select on app.master_build425_source_enrollment_evidence,app.master_build425_telemetry_acceptance_events,app.master_build425_sysop_procedure_evidence to ai_data_protected_runtime;revoke update,delete on app.master_build425_source_enrollment_evidence,app.master_build425_telemetry_acceptance_events,app.master_build425_sysop_procedure_evidence from ai_data_runtime,ai_data_protected_runtime;
